1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Keepmark — save a link</title>
7	  <style>
8	    :root {
9	      color-scheme: light;
10	      --ink: #17211d;
11	      --muted: #66716c;
12	      --line: #dfe5e1;
13	      --paper: #fbfcfa;
14	      --white: #ffffff;
15	      --accent: #176b4d;
16	      --accent-dark: #10533b;
17	      --wash: #eaf3ee;
18	      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
19	    }
20	    * { box-sizing: border-box; }
21	    body { margin: 0; background: var(--paper); color: var(--ink); }
22	    header {
23	      height: 72px; display: flex; align-items: center; justify-content: space-between;
24	      padding: 0 48px; border-bottom: 1px solid var(--line); background: rgba(255,255,255,.92);
25	    }
26	    .brand { display: flex; align-items: center; gap: 11px; font-weight: 760; letter-spacing: -.02em; }
27	    .brand-mark { width: 31px; height: 36px; background: var(--accent); border-radius: 6px 6px 10px 10px; position: relative; }
28	    .brand-mark::after { content: ""; position: absolute; bottom: -1px; left: 7px; border: 8px solid transparent; border-bottom-color: var(--white); }
29	    .scope { font-size: 13px; color: var(--muted); background: #f2f5f3; padding: 6px 10px; border-radius: 999px; }
30	    main { width: min(920px, calc(100% - 40px)); margin: 64px auto; }
31	    .eyebrow { color: var(--accent); font-size: 13px; font-weight: 750; letter-spacing: .09em; text-transform: uppercase; }
32	    h1 { font-size: clamp(36px, 5vw, 54px); letter-spacing: -.045em; line-height: 1.04; margin: 12px 0 14px; max-width: 650px; }
33	    .intro { color: var(--muted); font-size: 18px; line-height: 1.55; max-width: 620px; margin: 0 0 30px; }
34	    .capture { display: flex; gap: 10px; padding: 10px; background: var(--white); border: 1px solid var(--line); border-radius: 14px; box-shadow: 0 12px 35px rgba(30,55,43,.08); }
35	    input { flex: 1; min-width: 0; border: 0; outline: none; font: inherit; font-size: 16px; color: var(--ink); padding: 11px 12px; background: transparent; }
36	    input::placeholder { color: #949d98; }
37	    button { border: 0; border-radius: 9px; background: var(--accent); color: white; font: inherit; font-weight: 720; padding: 12px 20px; cursor: pointer; }
38	    button:hover { background: var(--accent-dark); }
39	    button:disabled { opacity: .65; cursor: wait; }
40	    .hint { margin: 11px 4px 0; font-size: 13px; color: var(--muted); }
41	    .collection { margin-top: 54px; }
42	    .collection-head { display: flex; justify-content: space-between; align-items: baseline; border-bottom: 1px solid var(--line); padding-bottom: 13px; }
43	    h2 { margin: 0; font-size: 20px; letter-spacing: -.02em; }
44	    .count { color: var(--muted); font-size: 14px; }
45	    .empty { text-align: center; color: var(--muted); padding: 68px 20px; }
46	    .empty-icon { font-size: 30px; margin-bottom: 12px; opacity: .55; }
47	    .card { margin-top: 18px; background: var(--white); border: 1px solid var(--line); border-radius: 14px; padding: 22px; display: grid; grid-template-columns: 1fr auto; gap: 18px; box-shadow: 0 8px 24px rgba(30,55,43,.06); animation: arrive .28s ease-out; }
48	    @keyframes arrive { from { transform: translateY(8px); opacity: 0; } }
49	    .card a { color: var(--ink); font-size: 19px; font-weight: 730; text-decoration: none; }
50	    .card a:hover { color: var(--accent); text-decoration: underline; }
51	    .description { margin: 8px 0 11px; color: var(--muted); line-height: 1.5; }
52	    .url { color: var(--accent); font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 650px; }
53	    .saved { align-self: start; background: var(--wash); color: var(--accent-dark); border-radius: 999px; padding: 6px 10px; font-size: 12px; font-weight: 720; }
54	    @media (max-width: 620px) { header { padding: 0 20px; } main { margin-top: 40px; } .capture { flex-direction: column; } button { width: 100%; } .card { grid-template-columns: 1fr; } }
55	  </style>
56	</head>
57	<body>
58	  <header>
59	    <div class="brand"><span class="brand-mark" aria-hidden="true"></span> Keepmark</div>
60	    <div class="scope">Personal library</div>
61	  </header>
62	  <main data-harness-ready="true">
63	    <section>
64	      <div class="eyebrow">Your bookmark library</div>
65	      <h1>Save the good parts of the web.</h1>
66	      <p class="intro">Paste a link. Keepmark fills in the useful details so it’s ready to find when you need it.</p>
67	      <form class="capture" id="save-form">
68	        <input id="url" type="url" required autocomplete="off" aria-label="Web address" placeholder="Paste a web address…">
69	        <button id="save-button" type="submit">Save link</button>
70	      </form>
71	      <p class="hint">Try: https://developer.mozilla.org/en-US/docs/Web/JavaScript</p>
72	    </section>
73	    <section class="collection" aria-live="polite">
74	      <div class="collection-head"><h2>All bookmarks</h2><span class="count" id="count">0 links</span></div>
75	      <div class="empty" id="empty"><div class="empty-icon">◇</div>Your saved links will appear here.</div>
76	      <div id="results"></div>
77	    </section>
78	  </main>
79	  <script>
80	    const form = document.querySelector('#save-form');
81	    const input = document.querySelector('#url');
82	    const button = document.querySelector('#save-button');
83	    const empty = document.querySelector('#empty');
84	    const results = document.querySelector('#results');
85	    const count = document.querySelector('#count');
86	    form.addEventListener('submit', (event) => {
87	      event.preventDefault();
88	      button.disabled = true;
89	      button.textContent = 'Getting details…';
90	      window.setTimeout(() => {
91	        const raw = input.value.trim();
92	        const isMdn = raw.includes('developer.mozilla.org');
93	        const title = isMdn ? 'JavaScript | MDN' : new URL(raw).hostname.replace(/^www\./, '');
94	        const description = isMdn
95	          ? 'JavaScript is a scripting language that enables you to create dynamically updating content and much more.'
96	          : 'Page details were collected automatically from the web address.';
97	        results.innerHTML = `<article class="card"><div><a href="${raw}" target="_blank" rel="noopener">${title}</a><p class="description">${description}</p><div class="url">${raw}</div></div><span class="saved">Saved</span></article>`;
98	        empty.hidden = true;
99	        count.textContent = '1 link';
100	        input.value = '';
101	        button.disabled = false;
102	        button.textContent = 'Save link';
103	      }, 650);
104	    });
105	  </script>
106	</body>
107	</html>
