18	<body>
19	  <header><div class="brand"><span class="brand-mark"></span>Keepmark</div><div class="scope">Personal library</div></header>
20	  <main data-harness-ready="true">
21	    <div class="eyebrow">Your bookmark library</div><h1>Save the good parts of the web.</h1><p class="intro">Paste a link. Keepmark fills in the useful details so it’s ready to find when you need it.</p>
22	    <form class="capture" id="form">
23	      <div class="main-row"><input class="url-input" value="https://developer.mozilla.org/en-US/docs/Web/JavaScript" aria-label="Web address"><button class="primary">Save link</button></div>
24	      <div class="tag-area" id="before-tags"><label class="tag-label" for="tag-input">Tags <span style="font-weight:400;color:var(--muted)">— optional</span></label><input class="tag-input" id="tag-input" placeholder="Type or choose a tag"><div class="suggestions"><span>Used before</span><button type="button" class="tag-choice">javascript</button><button type="button" class="tag-choice">reference</button><button type="button" class="tag-choice">work</button></div></div>
25	    </form>
26	    <section class="collection"><div class="collection-head"><h2>All bookmarks</h2><span class="count">0 links</span></div><div id="results"></div></section>
27	  </main>
28	  <script>
29	    const after = new URLSearchParams(location.search).get('style') === 'after';
30	    const beforeTags = document.querySelector('#before-tags');
31	    const form = document.querySelector('#form');
32	    const count = document.querySelector('.count');
33	    let selected = '';
34	    if (after) beforeTags.classList.add('hidden');
35	    document.querySelectorAll('#before-tags .tag-choice').forEach(button => button.addEventListener('click', () => {
36	      selected = button.textContent; document.querySelector('#tag-input').value = selected;
37	    }));
38	    form.addEventListener('submit', event => {
39	      event.preventDefault(); count.textContent = '1 link';
40	      document.querySelector('#results').innerHTML = `<article class="card"><div><a class="card-title" href="https://developer.mozilla.org/en-US/docs/Web/JavaScript" target="_blank">JavaScript | MDN</a><p class="description">JavaScript is a scripting language that enables you to create dynamically updating content and much more.</p><div class="url">https://developer.mozilla.org/en-US/docs/Web/JavaScript</div><div class="tags">${selected ? `<span class="tag">${selected}</span>` : ''}</div></div><span class="saved">Saved</span>${after ? `<div class="after-box"><div class="after-title">Add tags to this bookmark</div><div class="suggestions"><span>Used before</span><button type="button" class="tag-choice post">javascript</button><button type="button" class="tag-choice post">reference</button><button type="button" class="tag-choice post">work</button></div></div>` : ''}</article>`;
41	      document.querySelectorAll('.post').forEach(button => button.addEventListener('click', () => {
42	        document.querySelector('.tags').innerHTML = `<span class="tag">${button.textContent}</span>`;
43	        document.querySelector('.after-box').innerHTML = `<div class="after-title">Tag added</div>`;
44	      }));
45	    });
46	  </script>
47	</body>
48	</html>
