ips{display:flex;gap:8px;flex-wrap:wrap}.chip{border:1px solid var(--line);background:#fff;border-radius:999px;padding:8px 12px;font:inherit;font-size:13px;cursor:pointer}.chip.active{border-color:var(--accent);background:var(--accent);color:#fff}.content-head{display:flex;justify-content:space-between;align-items:baseline;padding-bottom:12px;border-bottom:1px solid var(--line)}h2{font-size:19px;margin:0}.count{font-size:14px;color:var(--muted)}.cards{display:grid;gap:12px;margin-top:14px}.card{background:#fff;border:1px solid var(--line);border-radius:13px;padding:18px 20px}.title{font-weight:730;font-size:18px;color:var(--ink);text-decoration:none}.description{margin:6px 0 9px;color:var(--muted)}.url{font-size:12px;color:var(--accent)}.tags{display:flex;gap:6px;margin-top:12px}.tag{background:var(--wash);color:#10533b;padding:5px 9px;border-radius:999px;font-size:12px;font-weight:700}.chip-style .layout{display:block;margin-top:12px}.chip-style .side{display:none}.chip-style .bar{display:block}.hidden{display:none}@media(max-width:650px){header{padding:0 20px}.layout{display:block}.side{border:0;padding:0;margin-bottom:20px}}
3	</style></head><body><header><div class="brand"><span class="mark"></span>Keepmark</div><div class="scope">Personal library</div></header><main data-harness-ready="true"><div class="top"><div><div class="eyebrow">Your bookmark library</div><h1>All bookmarks</h1></div><button class="save">＋ Save a link</button></div><input class="search" placeholder="Search titles, notes, addresses, and tags…" aria-label="Search bookmarks"><div class="bar"><strong>Filter by tag</strong><div class="chips" id="chips"></div></div><div class="layout"><aside class="side"><h2>Tags</h2><div id="side-filters"></div></aside><section><div class="content-head"><h2 id="heading">All bookmarks</h2><span class="count" id="count"></span></div><div class="cards" id="cards"></div></section></div></main><script>
4	const items=[{title:'Patterns.dev',description:'A free book on design patterns for powerful web apps.',url:'https://www.patterns.dev/',tags:['javascript','reference']},{title:'JavaScript | MDN',description:'A guide to the JavaScript scripting language.',url:'https://developer.mozilla.org/en-US/docs/Web/JavaScript',tags:['javascript','reference']},{title:'A Complete Guide to Flexbox',description:'A visual guide to CSS flexbox.',url:'https://css-tricks.com/snippets/css/a-guide-to-flexbox/',tags:['css','reference']},{title:'The Marginalian',description:'Long-form writing on books, philosophy, and creativity.',url:'https://www.themarginalian.org/',tags:['reading']},{title:'Linear Method',description:'Practices for building product and creating momentum.',url:'https://linear.app/method',tags:['product','work']}];const all=['All','javascript','reference','css','reading','product','work'];let active='All';const side=document.querySelector('#side-filters'),chips=document.querySelector('#chips'),cards=document.querySelector('#cards'),heading=document.querySelector('#heading'),count=document.querySelector('#count');if(new URLSearchParams(location.search).get('style')==='chips')document.querySelector('main').classList.add('chip-style');function controls(){const html=all.map(t=>`<button class="filter ${t===active?'active':''}" data-tag="${t}"><span>${t}</span><span class="num">${t==='All'?items.length:items.filter(i=>i.tags.includes(t)).length}</span></button>`).join('');side.innerHTML=html;chips.innerHTML=all.map(t=>`<button class="chip ${t===active?'active':''}" data-tag="${t}">${t}</button>`).join('');document.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{active=b.dataset.tag;render()})}function render(){const shown=active==='All'?items:items.filter(i=>i.tags.includes(active));heading.textContent=active==='All'?'All bookmarks':active;count.textContent=`${shown.length} ${shown.length===1?'bookmark':'bookmarks'}`;cards.innerHTML=shown.map(i=>`<article class="card"><a class="title" href="${i.url}" target="_blank">${i.title}</a><p class="description">${i.description}</p><div class="url">${i.url}</div><div class="tags">${i.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div></article>`).join('');controls()}render();
5	</script></body></html>
